import os,json,subprocess,re
from pathlib import Path
root=Path("/srv/projects/Engenheira-reversa")
cli=root/"runtime/bin/rea-mcp"
repo=root/"original"
out={"read_only":True,"cli_exists":cli.exists(),"cli_symlink":cli.is_symlink(),"source_exists":repo.is_dir(),"runtime_exists":(root/"runtime").is_dir(),"path_tests":{}}
if cli.is_symlink():out["cli_target"]=os.readlink(cli)
if cli.is_file() and cli.stat().st_size<10000:
 text=cli.read_text(errors="replace")
 out["cli_lines"]=[line[:350] for line in text.splitlines()[:50] if not re.search("(TOKEN|SECRET|PASSWORD|AUTH)",line,re.I)]
for name,p in (("src_node",(repo/"node_modules")),("runtime_node",(root/"runtime/node_modules")),("runtime_vendors",(root/"runtime/vendors"))):
 out["path_tests"][name]={"is_dir":p.is_dir(),"link":p.is_symlink(),"target":os.readlink(p) if p.is_symlink() else None}
if cli.is_file():
 try:
  init='{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-03-26","capabilities":{},"clientInfo":{"name":"rea-health-probe","version":"1"}}}\n'
  p=subprocess.run(["runuser","-u","ubuntu","--",str(cli)],input=init,capture_output=True,text=True,timeout=20)
  out["mcp_exit"]=p.returncode
  out["mcp_stdout_prefix"]=p.stdout[:550]
  stderr=p.stderr[:1300]
  stderr=re.sub(r"(?i)(token|secret|password|authorization)[^\n]*","[redacted]",stderr)
  out["mcp_stderr_prefix"]=stderr
 except subprocess.TimeoutExpired:
  out["mcp_exit"]="TIMEOUT"
print(json.dumps(out,ensure_ascii=True,sort_keys=True))
